import{_ as o,o as t,c as n,aB as a}from"./chunks/framework.BrtqxvdK.js";const g=JSON.parse('{"title":"Swagger 2.0 → OpenAPI 3.0 conversion","description":"","frontmatter":{},"headers":[],"relativePath":"spec-conversion.md","filePath":"spec-conversion.md","lastUpdated":null}'),i={name:"spec-conversion.md"};function r(s,e,d,p,c,l){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="Swagger-2.0-OpenAPI-3.0-conversion" tabindex="-1">Swagger 2.0 → OpenAPI 3.0 conversion <a class="header-anchor" href="#Swagger-2.0-OpenAPI-3.0-conversion" aria-label="Permalink to &quot;Swagger 2.0 → OpenAPI 3.0 conversion {#Swagger-2.0-OpenAPI-3.0-conversion}&quot;">​</a></h1><p>The <code>OpenAPISpec</code> plugin accepts both Swagger 2.0 and OpenAPI 3.x specs. Swagger 2.0 specs are normalised to OpenAPI 3.0 in place.</p><h2 id="Why" tabindex="-1">Why <a class="header-anchor" href="#Why" aria-label="Permalink to &quot;Why {#Why}&quot;">​</a></h2><p>Three layers of the scaffold consume the spec, and they have different version support:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Layer</th><th style="text-align:right;">OAS 2.0</th><th style="text-align:right;">OAS 3.x</th></tr></thead><tbody><tr><td style="text-align:right;"><code>openapi-generator-cli julia-client</code> (codegen)</td><td style="text-align:right;">✅</td><td style="text-align:right;">✅</td></tr><tr><td style="text-align:right;">Bundled <code>spec/openapi.json</code></td><td style="text-align:right;">(saved as-is)</td><td style="text-align:right;">(saved as-is)</td></tr><tr><td style="text-align:right;"><code>vitepress-openapi</code> (docs interactive browser)</td><td style="text-align:right;">❌ — silently empty</td><td style="text-align:right;">✅</td></tr></tbody></table><p>If we left the spec as 2.0, the docs site would render the page chrome but no endpoints. So when a Swagger 2.0 spec is detected, the plugin runs <code>npx swagger2openapi</code> over it before anything else.</p><h2 id="How" tabindex="-1">How <a class="header-anchor" href="#How" aria-label="Permalink to &quot;How {#How}&quot;">​</a></h2><p>After <code>_save_spec</code> writes the original to <code>spec/openapi.json</code>, the plugin scans the first 1 KB for a top-level <code>&quot;swagger&quot;: &quot;2.x&quot;</code> key:</p><ul><li><p>If absent (or <code>&quot;openapi&quot;: &quot;3&quot;</code> is present) — no-op.</p></li><li><p>If present — copy <code>spec/openapi.json</code> to <code>spec/openapi.v2-original.json</code>, then run <code>npx --yes swagger2openapi@7.0.8 spec/openapi.json -o spec/openapi.json</code> to overwrite in place. An <code>@info</code> log records what happened.</p></li></ul><p>After conversion:</p><ul><li><p><code>spec/openapi.json</code> is OAS 3.0.x</p></li><li><p><code>spec/openapi.v2-original.json</code> preserves the original for reference</p></li><li><p>Codegen runs against the converted spec (the generator handles both, but using the converted form keeps a single source of truth)</p></li><li><p>The docs site picks up the converted form via <code>cp(spec/openapi.json -&gt; docs/src/public/openapi.json)</code> in <code>make.jl</code></p></li></ul><h2 id="Failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#Failure-modes" aria-label="Permalink to &quot;Failure modes {#Failure-modes}&quot;">​</a></h2><ul><li><p><strong><code>npx</code> not on PATH</strong> — the plugin throws a friendly error pointing at the <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node installation page</a>. <code>swagger2openapi</code> is the only Node dep needed for v2 conversion (codegen also uses <code>npx</code> to run <code>openapi-generator-cli</code>, so Node is needed for both).</p></li><li><p><strong>Spec is malformed</strong> — <code>swagger2openapi</code> exits non-zero and the plugin re-throws. The original v2 file is still on disk; nothing has been overwritten yet because the conversion is the last write step.</p></li></ul><h2 id="Disabling-the-conversion" tabindex="-1">Disabling the conversion <a class="header-anchor" href="#Disabling-the-conversion" aria-label="Permalink to &quot;Disabling the conversion {#Disabling-the-conversion}&quot;">​</a></h2><p>If you want to keep a Swagger 2.0 spec untouched (e.g. you don&#39;t ship docs and prefer to feed the original to codegen), drop the <code>OpenAPISpec</code> plugin from your template and hand-roll the few file writes you need. <code>OpenAPISpec</code> doesn&#39;t currently expose a <code>convert_swagger=false</code> knob — file an issue if you need one.</p>',15)])])}const u=o(i,[["render",r]]);export{g as __pageData,u as default};
